data.iecDecl:
ST_Ausstattung: STRUCT
	Box2 : BOOL;
	Luftaufbereiter : BOOL;
	Abluftventilator : BOOL;
	SensorFrischluft : BOOL;
	SensorAbluftBox1 : BOOL;
	SensorAbluftBox2 : BOOL;
	SensorTrockenluft : BOOL;
	SensorStocktemp : BOOL;
	EndlagenVhdBoxenklappe1 : BOOL;
	EndlagenVhdBoxenklappe2 : BOOL;
END_STRUCT;

ST_IoTestDigitalOut: STRUCT
	doFrgLuftaufber : BOOL;
	doFrgBox1 : BOOL;
	doFrgBox2 : BOOL;
	doFrgAbluftventilator : BOOL;
	doFrgVentilator		  : BOOL;
END_STRUCT;

ST_StatAnlage: STRUCT
	Aktor : ARRAY[0..39] OF eStatus;
	FrischluftTemperatur : REAL;
	FrischluftFeuchte : REAL;
	TrockenluftTemperatur : REAL;
	TrockenluftFeuchte : REAL;
	StockTemperatur : REAL;
	AbluftBox1Temp : REAL;
	AbluftBox1Feuchte : REAL;
	AbluftBox2Temp : REAL;
	AbluftBox2Feuchte : REAL;
END_STRUCT;

ST.xhtml:p:
(* ================================================================================ File : IOMappingCyclic.st Project : CControl_Lite Controller : Schneider / EcoStruxure Machine Expert HVAC Author : RIG Automation Created : 2026-03-17 Version : V0.02 Description : Hauptprogramm für die I/O-Anbindung CControl_Lite
Diese Programmversion bildet die aktuell im neuen ST-Code vorgesehenen digitalen und analogen Ein-/Ausgänge.
Implementiert sind: - Einlesen der digitalen Eingänge - Einlesen und Aufbereitung der analogen Eingänge - Filterung der Frischlufttemperatur über gleitenden Mittelwert - Lineare Skalierung der analogen Rohwerte - Ausgabe digitaler Freigaben - Ausgabe analoger Sollwerte - I/O-Testbetrieb mit direkter Aktoransteuerung
================================================================================ Change History -------------------------------------------------------------------------------- Version | Date | Author | Description -------------------------------------------------------------------------------- V0.00 | 2026-03-17 | RIG | Erstversion mit Grundgerüst für | Normalbetrieb und Testbetrieb ================================================================================ *)
// INIT BOOL IBN_TRUE := TRUE; IBN_FALSE := FALSE;
(* =============================================================================== EINMALIGE INITIALISIERUNG ------------------------------------------------------------------------------- Initialwerte für Parameter und Ausstattung. Diese Initialisierung erfolgt nur einmal nach dem Start der Steuerung. =============================================================================== *) IF NOT gInitDone THEN gInitDone := TRUE; END_IF;
gQuitErr := HMI_IN_diQuitErr;
(* =============================================================================== BETRIEBSARTUMSCHALTUNG ------------------------------------------------------------------------------- Im Normalbetrieb werden Ein-/Ausgänge durch die Programmlogik verarbeitet. Im I/O-Testbetrieb werden Ausgänge direkt aus der Teststruktur angesteuert. =============================================================================== *) IF gAktModus <> IOTEST THEN
(* =========================================================================== NORMALBETRIEB =========================================================================== *)
(* --------------------------------------------------------------------------- Digitale Eingänge einlesen --------------------------------------------------------------------------- Zuordnung der Hardware-Eingänge auf interne Prozessvariablen. --------------------------------------------------------------------------- *)
diBox1Offen := hw_di1; diBox1Geschl := hw_di2; diBox2Offen := hw_di3; diBox2Geschl := hw_di4; diBetriebLuftaufber := hw_di5; diStoerLuftaufber := hw_di6;
(* --------------------------------------------------------------------------- Analoge Rohwerte einlesen und in REAL umwandeln --------------------------------------------------------------------------- *) rFrischluftTempRaw := TO_REAL(hw_ai1); rFrischluftFeuchtRaw := TO_REAL(hw_ai2); rAbluftBox1TempRaw := TO_REAL(hw_ai3); rAbluftBox1FeuchtRaw := TO_REAL(hw_ai4); rTrockenluftTempRaw := TO_REAL(hw_ai3); rTrockenluftFeuchtRaw := TO_REAL(hw_ai4); rAbluftBox2TempRaw := TO_REAL(hw_ai5); rAbluftBox2FeuchtRaw := TO_REAL(hw_ai6); rStocktempRaw := TO_REAL(hw_ai7);
(* --------------------------------------------------------------------------- Frischlufttemperatur filtern --------------------------------------------------------------------------- Die Frischlufttemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbFrischluftTempAvg( enable := TRUE, x := rFrischluftTempRaw, base := gBetriebsparameter.Sensoren.FilterzeitFrischluft );
(* --------------------------------------------------------------------------- Frischlufttemperatur skalieren --------------------------------------------------------------------------- Rohwert 0..32767 -> Engineering-Wert gemäß parametriertem Messbereich. Anschließend wird der parametrierte Offset addiert. --------------------------------------------------------------------------- *)
fbFrischluftTempScal( x := fbFrischluftTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.FrischlTempMessberMax ); aiFrischluftTemp := fbFrischluftTempScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftTemp;
(* --------------------------------------------------------------------------- Frischluftfeuchte skalieren --------------------------------------------------------------------------- *) fbFrischluftFeuchtScal( x := rFrischluftFeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax ); aiFrischluftFeucht := fbFrischluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte;
(* --------------------------------------------------------------------------- Abluft Box 1 skalieren --------------------------------------------------------------------------- *) fbAbluftBox1TempScal( x := rAbluftBox1TempRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); aiAbluftBox1Temp := fbAbluftBox1TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp;
fbAbluftBox1FeuchtScal( x := rAbluftBox1FeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); aiAbluftBox1Feucht := fbAbluftBox1FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte;
(* --------------------------------------------------------------------------- Trockenluft skalieren --------------------------------------------------------------------------- Aktuell werden hierfür dieselben Rohwerte wie für Abluft Box 1 verwendet, weil dies im aktuellen Projektstand so vorgesehen ist. --------------------------------------------------------------------------- *) fbTrockenluftTempScal( x := rTrockenluftTempRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.TrockenlTempMessberMax ); aiTrockenluftTemp := fbTrockenluftTempScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftTemp;
fbTrockenluftFeuchtScal( x := rTrockenluftFeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax ); aiTrockenluftFeucht := fbTrockenluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte;
(* --------------------------------------------------------------------------- Abluft Box 2 skalieren --------------------------------------------------------------------------- *) fbAbluftBox2TempScal( x := rAbluftBox2TempRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); aiAbluftBox2Temp := fbAbluftBox2TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp;
fbAbluftBox2FeuchtScal( x := rAbluftBox2FeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); aiAbluftBox2Feucht := fbAbluftBox2FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte;
(* --------------------------------------------------------------------------- Stocktemperatur skalieren --------------------------------------------------------------------------- *) fbStocktempScal( x := rStocktempRaw, x1 := 0.0, y1 := 0.0, x2 := 32767.0, y2 := 100.0 ); aiStocktemp := fbStocktempScal.y + gBetriebsparameter.Sensoren.OffsetStocktemp;
(* --------------------------------------------------------------------------- Digitale Ausgänge auf Hardware schreiben --------------------------------------------------------------------------- Interne Freigaben werden auf die physikalischen Ausgänge geschrieben. --------------------------------------------------------------------------- *) hw_do1 := doFrgLuftaufber; hw_do2 := doFrgBox1; hw_do3 := doFrgBox2; hw_do4 := doFrgAbluftventilator; hw_do5 := doFrgVentilator;
(* --------------------------------------------------------------------------- Analogausgang FU-Ventilator skalieren --------------------------------------------------------------------------- Sollwertbereich 0..100 % -> Hardware-Rohwert 0..32767 --------------------------------------------------------------------------- *) fbAoFuVentilatorScal( x := aoFuVentilator, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 32767.0 ); hw_ao1 := TO_INT(fbAoFuVentilatorScal.y);
(* --------------------------------------------------------------------------- Analogausgang Leistungsvorgabe Luftaufbereiter skalieren --------------------------------------------------------------------------- Sollwertbereich 0..100 % -> Hardware-Rohwert 0..32767 --------------------------------------------------------------------------- *) fbAoLuftaufberLeistungScal( x := aoLeistVorgLuftaufber, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 32767.0 ); hw_ao4 := TO_INT(fbAoLuftaufberLeistungScal.y);
(* --------------------------------------------------------------------------- Testausgänge HMI zurücksetzen --------------------------------------------------------------------------- Sobald der I/O-Testbetrieb nicht aktiv ist, werden die Test-Sollwerte der HMI vorsorglich zurückgesetzt. Dadurch bleiben keine alten Testwerte stehen. --------------------------------------------------------------------------- *)
HMI_TEST_doFrgLuftaufber := FALSE; HMI_TEST_doFrgBox1 := FALSE; HMI_TEST_doFrgBox2 := FALSE; HMI_TEST_doFrgAbluftventilator := FALSE;
HMI_TEST_aoFuVentilator := 0.0; HMI_TEST_aoLeistVorgLuftaufber := 0.0;
ELSE
(* =========================================================================== I/O-TESTBETRIEB =========================================================================== Im Testbetrieb werden die Hardware-Ausgänge direkt über die Teststruktur angesteuert. Eingänge und Messwerte werden für Diagnosezwecke in die Teststruktur übernommen. =========================================================================== *)
(* --------------------------------------------------------------------------- Digitale Eingänge in Teststruktur übernehmen --------------------------------------------------------------------------- *) gIoTest.DigitalIn.diBox1Offen := hw_di1; gIoTest.DigitalIn.diBox1Geschl := hw_di2; gIoTest.DigitalIn.diBox2Offen := hw_di3; gIoTest.DigitalIn.diBox2Geschl := hw_di4; gIoTest.DigitalIn.diBetriebLuftaufber := hw_di5; gIoTest.DigitalIn.diStoerLuftaufber := hw_di6;
(* --------------------------------------------------------------------------- Analoge Eingänge im Testbetrieb aufbereiten --------------------------------------------------------------------------- Auch im Testbetrieb werden die Messwerte skaliert, damit am HMI direkt Engineering-Werte sichtbar sind. --------------------------------------------------------------------------- *) fbFrischluftTempAvg( enable := TRUE, x := TO_REAL(hw_ai1), base := gBetriebsparameter.Sensoren.FilterzeitFrischluft );
fbFrischluftTempScal( x := fbFrischluftTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.FrischlTempMessberMax ); gIoTest.AnalogIn.aiFrischluftTemp := fbFrischluftTempScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftTemp;
fbFrischluftFeuchtScal( x := TO_REAL(hw_ai2), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax ); gIoTest.AnalogIn.aiFrischluftFeuchte := fbFrischluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte;
fbAbluftBox1TempScal( x := TO_REAL(hw_ai3), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); gIoTest.AnalogIn.aiAbluftBox1Temp := fbAbluftBox1TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp;
fbAbluftBox1FeuchtScal( x := TO_REAL(hw_ai4), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); gIoTest.AnalogIn.aiAbluftBox1Feucht := fbAbluftBox1FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte;
fbTrockenluftTempScal( x := TO_REAL(hw_ai3), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.TrockenlTempMessberMax ); gIoTest.AnalogIn.aiTrockenluftTemp := fbTrockenluftTempScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftTemp;
fbTrockenluftFeuchtScal( x := TO_REAL(hw_ai4), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax ); gIoTest.AnalogIn.aiTrockenluftFeucht := fbTrockenluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte;
fbAbluftBox2TempScal( x := TO_REAL(hw_ai5), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); gIoTest.AnalogIn.aiAbluftBox2Temp := fbAbluftBox2TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp;
fbAbluftBox2FeuchtScal( x := TO_REAL(hw_ai6), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 32767.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); gIoTest.AnalogIn.aiAbluftBox2Feucht := fbAbluftBox2FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte;
fbStocktempScal( x := TO_REAL(hw_ai7), x1 := 0.0, y1 := 0.0, x2 := 32767.0, y2 := 100.0 ); gIoTest.AnalogIn.aiStocktemp := fbStocktempScal.y + gBetriebsparameter.Sensoren.OffsetStocktemp;
(* --------------------------------------------------------------------------- Digitale Testausgänge direkt auf Hardware schreiben --------------------------------------------------------------------------- *) hw_do1 := gIoTest.DigitalOut.doFrgLuftaufber; hw_do2 := gIoTest.DigitalOut.doFrgBox1; hw_do3 := gIoTest.DigitalOut.doFrgBox2; hw_do4 := gIoTest.DigitalOut.doFrgAbluftventilator; hw_do5 := gIoTest.DigitalOut.doFrgVentilator;
(* --------------------------------------------------------------------------- Analoge Testausgänge skalieren und auf Hardware schreiben --------------------------------------------------------------------------- *) fbAoFuVentilatorScal( x := gIoTest.AnalogOut.aoFuVentilator, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 32767.0 ); hw_ao1 := TO_INT(fbAoFuVentilatorScal.y);
fbAoLuftaufberLeistungScal( x := gIoTest.AnalogOut.aoLeistVorgLuftaufber, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 32767.0 ); hw_ao4 := TO_INT(fbAoLuftaufberLeistungScal.y);
END_IF;

(*
================================================================================
File        : BerechnungCyclic.st
Project     : CControl_Lite
Description :
    Basisberechnungen/Plausibilisierung Lite.
================================================================================
*)

(* Plausibilisierung *)
xFrischluftTempOk   := (aiFrischluftTemp >= -40.0) AND (aiFrischluftTemp <= 80.0);
xFrischluftFeuchtOk := (aiFrischluftFeucht >= 0.0) AND (aiFrischluftFeucht <= 100.0);

xAbluft1TempOk      := (aiAbluftBox1Temp >= -40.0) AND (aiAbluftBox1Temp <= 100.0);
xAbluft1FeuchtOk    := (aiAbluftBox1Feucht >= 0.0) AND (aiAbluftBox1Feucht <= 100.0);

xTrockenTempOk      := (aiTrockenluftTemp >= -40.0) AND (aiTrockenluftTemp <= 100.0);
xTrockenFeuchtOk    := (aiTrockenluftFeucht >= 0.0) AND (aiTrockenluftFeucht <= 100.0);

IF gBetriebsparameter.Ausstattung.Box2 THEN
    xAbluft2TempOk   := (aiAbluftBox2Temp >= -40.0) AND (aiAbluftBox2Temp <= 100.0);
    xAbluft2FeuchtOk := (aiAbluftBox2Feucht >= 0.0) AND (aiAbluftBox2Feucht <= 100.0);
ELSE
    xAbluft2TempOk   := TRUE;
    xAbluft2FeuchtOk := TRUE;
END_IF;

xStockTempOk := (aiStocktemp >= -40.0) AND (aiStocktemp <= 140.0);

(* Kennwerte *)
IF xAbluft1TempOk AND xFrischluftTempOk THEN
    rDeltaTempBox1 := aiAbluftBox1Temp - aiFrischluftTemp;
ELSE
    rDeltaTempBox1 := 0.0;
END_IF;

IF gBetriebsparameter.Ausstattung.Box2 AND xAbluft2TempOk AND xFrischluftTempOk THEN
    rDeltaTempBox2 := aiAbluftBox2Temp - aiFrischluftTemp;
ELSE
    rDeltaTempBox2 := 0.0;
END_IF;

IF xAbluft1FeuchtOk AND xFrischluftFeuchtOk THEN
    rDeltaFeuchteBox1 := aiAbluftBox1Feucht - aiFrischluftFeucht;
ELSE
    rDeltaFeuchteBox1 := 0.0;
END_IF;

IF gBetriebsparameter.Ausstattung.Box2 AND xAbluft2FeuchtOk AND xFrischluftFeuchtOk THEN
    rDeltaFeuchteBox2 := aiAbluftBox2Feucht - aiFrischluftFeucht;
ELSE
    rDeltaFeuchteBox2 := 0.0;
END_IF;

(* Sammelstörung auf Schrittkette, wenn Sensorik unplausibel *)
IF NOT (xFrischluftTempOk AND xFrischluftFeuchtOk
        AND xAbluft1TempOk AND xAbluft1FeuchtOk
        AND xTrockenTempOk AND xTrockenFeuchtOk
        AND xAbluft2TempOk AND xAbluft2FeuchtOk
        AND xStockTempOk) THEN

    IF gAktModus <> IOTEST THEN
        gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_STOERUNG;
    END_IF;
END_IF;

data.iecDecl:
PROGRAM BerechnungCyclic

VAR
    xFrischluftTempOk : BOOL;
    xFrischluftFeuchtOk : BOOL;
    xAbluft1TempOk : BOOL;
    xAbluft1FeuchtOk : BOOL;
    xTrockenTempOk : BOOL;
    xTrockenFeuchtOk : BOOL;
    xAbluft2TempOk : BOOL;
    xAbluft2FeuchtOk : BOOL;
    xStockTempOk : BOOL;

    rDeltaTempBox1 : REAL;
    rDeltaTempBox2 : REAL;
    rDeltaFeuchteBox1 : REAL;
    rDeltaFeuchteBox2 : REAL;
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : MainControl.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-13
 Version     : V0.01
 Description :
    Vereinfachte Ablaufsteuerung für die reduzierte CControl_Lite Variante.

    Diese Version enthält nur die tatsächlich vorhandenen Funktionen und Aktoren.
    Die Struktur orientiert sich an der Legacy-Schrittkette, wurde jedoch bewusst
    auf die im Projekt vorhandene Hardware reduziert.

    Enthalten:
      - Statusaktualisierung
      - einfache Ablaufsteuerung
      - Stillstand / Betrieb / I/O-Test
      - direkte Ansteuerlogik für vorhandene Aktoren

 Change History
 --------------------------------------------------------------------------------
 Version | Date       | Author          | Description
 --------------------------------------------------------------------------------
 V0.01   | 2026-04-13 | RIG Automation  | Initiale reduzierte Ablaufsteuerung
================================================================================
*)


// =============================================================================
// 1) Statusaktualisierung
// =============================================================================

// Analoge Istwerte auf Status schreiben
gStatusAnlage.FrischluftTemperatur 	:= aiFrischluftTemp;
gStatusAnlage.FrischluftFeuchte 	:= aiFrischluftFeucht;
gStatusAnlage.TrockenluftTemperatur := aiTrockenluftTemp;
gStatusAnlage.TrockenluftFeuchte 	:= aiTrockenluftFeucht;
gStatusAnlage.AbluftBox1Temp 		:= aiAbluftBox1Temp;
gStatusAnlage.AbluftBox1Feuchte 	:= aiAbluftBox1Feucht;
gStatusAnlage.AbluftBox2Temp 		:= aiAbluftBox2Temp;
gStatusAnlage.AbluftBox2Feuchte 	:= aiAbluftBox2Feucht;
gStatusAnlage.StockTemperatur 		:= aiStocktemp;


// =============================================================================
// 2) Bedienbefehle auswerten
// =============================================================================
xStartFreigabe   := gCmdAnlage.Start AND gCmdAnlage.Auto;
xStopAnforderung := gCmdAnlage.Stopp;
xTestbetrieb     := gCmdAnlage.Test AND NOT gCmdAnlage.Auto;

// =============================================================================
// 3) Aktuellen Zustand übernehmen
// =============================================================================
gAktModus := nextModus;


// =============================================================================
// 4) Schrittkette
// =============================================================================
CASE gAktModus OF

    // *************************************************************************
    // STILLSTAND
    // *************************************************************************
    0:
        IF stateEntry THEN
            stateEntry := FALSE;

            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_STILLSTAND;
        END_IF;

        // ------------------------------------------------------------
        // Stillstandslogik - nur vorhandene Aktoren
        // ------------------------------------------------------------
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;
        gAktoren.xFrgLuftaufbereiter := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;

        aoFuVentilator := 0.0;
        aoLeistVorgLuftaufber := 0.0;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF xStartFreigabe THEN
            nextModus := BETRIEB;
            stateEntry := TRUE;

        ELSIF xTestbetrieb THEN
            nextModus := IOTEST;
            stateEntry := TRUE;

        ELSE
            nextModus := gAktModus;
        END_IF;


    // *************************************************************************
    // BETRIEB
    // *************************************************************************
    1:
        IF stateEntry THEN
            stateEntry := FALSE;

            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_ANLAGE_IN_BETRIEB;
            hmiNutzungsdaten.LetzterModus := BETRIEB;
        END_IF;

        // ------------------------------------------------------------
        // Betriebslogik - nur vorhandene Aktoren
        // ------------------------------------------------------------

        // Boxfreigaben
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;

        // Luftaufbereiter freigeben
        gAktoren.xFrgLuftaufbereiter := FALSE;

        // Abluftventilator freigeben
        gAktoren.xFrgAbluftventilator := FALSE;

        // Analoge Sollwerte
        aoFuVentilator := gCmdAnlage.Leistung.DrehzahlVentilator;
        aoLeistVorgLuftaufber := gCmdAnlage.Leistung.DrehzahlLuftaufbereitung;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF xStopAnforderung THEN
            hmiNutzungsdaten.LetzterModus := STILLSTAND;
            nextModus := STILLSTAND;
            stateEntry := TRUE;
        ELSE
            nextModus := gAktModus;
        END_IF;


    // *************************************************************************
    // IOTEST
    // *************************************************************************
    2:
        IF stateEntry THEN
            stateEntry := FALSE;

            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_TESTBETRIEB;
        END_IF;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF NOT xTestbetrieb THEN
            nextModus := STILLSTAND;
            stateEntry := TRUE;
        ELSE
            nextModus := gAktModus;
        END_IF;

END_CASE;

(*
================================================================================
File        : LeistungCyclic.st
Project     : CControl_Lite
Description :
    Leistungsregelung Lite ohne Luftgeschwindigkeitssensor.
    Ventilator regelt auf Trockenluft-Feuchte (PIDAdvanced), falls verfügbar.
    Sonst manuelle Vorgabe.
================================================================================
*)

(* Sollwerte begrenzen *)
rVentSollMan := gCmdAnlage.Leistung.DrehzahlVentilator;
IF rVentSollMan < 0.0 THEN
    rVentSollMan := 0.0;
ELSIF rVentSollMan > 100.0 THEN
    rVentSollMan := 100.0;
END_IF;

rLuftaufbSoll := gCmdAnlage.Leistung.DrehzahlLuftaufbereitung;
IF rLuftaufbSoll < 0.0 THEN
    rLuftaufbSoll := 0.0;
ELSIF rLuftaufbSoll > 100.0 THEN
    rLuftaufbSoll := 100.0;
END_IF;

gAktoren.rVentilatorSollwert := rVentSollMan;
gAktoren.rLuftaufbereiterSollwert := rLuftaufbSoll;

CASE gAktModus OF

    STILLSTAND:
        gAktoren.xFrgVentilator       := FALSE;
        gAktoren.xFrgLuftaufbereiter  := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;

        aoFuVentilator := 0.0;
        aoLeistVorgLuftaufber := 0.0;

        (* PID deaktiviert *)
        fbPidVent(
            xEn := FALSE,
            rPv := aiTrockenluftFeucht,
            rSetp := rTrockenluftFeuchteSoll,
            xManualMode := TRUE,
            rManualValue := 0.0,
            xHold := FALSE,
            rHighLimit := rVentHighLimit,
            rLowLimit := rVentLowLimit,
            rDeadband := rVentDeadband,
            xAutoTune := FALSE,
            rAutoTuneValue := 0.0,
            rKp := rVentKp,
            uiTi := uiVentTi,
            uiTd := uiVentTd,
            xReset := FALSE
        );

    BETRIEB:
        gAktoren.xFrgVentilator := TRUE;
        gAktoren.xFrgLuftaufbereiter := gBetriebsparameter.Ausstattung.Luftaufbereiter;
        gAktoren.xFrgAbluftventilator := gBetriebsparameter.Ausstattung.Abluftventilator;

        xVentPidFreigabe := gBetriebsparameter.Ausstattung.SensorTrockenluft
                            AND (aiTrockenluftFeucht >= 0.0)
                            AND (aiTrockenluftFeucht <= 100.0);

        rFeuchteSoll := rTrockenluftFeuchteSoll;

        (* PID-Reset-Puls bei Quit *)
        xPidResetReq := gQuitErr;
        xPidResetPulse := xPidResetReq AND NOT xPidResetEdgeMem;
        xPidResetEdgeMem := xPidResetReq;

        IF xVentPidFreigabe THEN
            (* Automatikbetrieb *)
            fbPidVent(
                xEn := TRUE,
                rPv := aiTrockenluftFeucht,
                rSetp := rFeuchteSoll,
                xManualMode := FALSE,
                rManualValue := rVentSollMan,
                xHold := FALSE,
                rHighLimit := rVentHighLimit,
                rLowLimit := rVentLowLimit,
                rDeadband := rVentDeadband,
                xAutoTune := FALSE,
                rAutoTuneValue := 0.0,
                rKp := rVentKp,
                uiTi := uiVentTi,
                uiTd := uiVentTd,
                xReset := xPidResetPulse
            );

            rVentPidOut := fbPidVent.rAnalog;

            IF rVentPidOut < 0.0 THEN
                aoFuVentilator := 0.0;
            ELSIF rVentPidOut > 100.0 THEN
                aoFuVentilator := 100.0;
            ELSE
                aoFuVentilator := rVentPidOut;
            END_IF;
        ELSE
            (* kein gültiger Prozesswert -> manueller Fallback *)
            fbPidVent(
                xEn := TRUE,
                rPv := aiTrockenluftFeucht,
                rSetp := rFeuchteSoll,
                xManualMode := TRUE,
                rManualValue := rVentSollMan,
                xHold := FALSE,
                rHighLimit := rVentHighLimit,
                rLowLimit := rVentLowLimit,
                rDeadband := rVentDeadband,
                xAutoTune := FALSE,
                rAutoTuneValue := 0.0,
                rKp := rVentKp,
                uiTi := uiVentTi,
                uiTd := uiVentTd,
                xReset := xPidResetPulse
            );
            aoFuVentilator := rVentSollMan;
        END_IF;

        (* Diagnose vom PID *)
        rPidErr := fbPidVent.rError;
        uiPidAlarm := fbPidVent.uiAlarmID;
        uiPidAlert := fbPidVent.uiAlertID;

        (* Luftaufbereiter *)
        IF gAktoren.xFrgLuftaufbereiter THEN
            IF gBetriebsparameter.Ausstattung.SensorTrockenluft THEN
                aoLeistVorgLuftaufber := rLuftaufbSoll;
            ELSE
                aoLeistVorgLuftaufber := 0.0;
            END_IF;
        ELSE
            aoLeistVorgLuftaufber := 0.0;
        END_IF;

    IOTEST:
        gAktoren.xFrgVentilator       := FALSE;
        gAktoren.xFrgLuftaufbereiter  := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;

        (* PID nicht aktiv im IOTEST *)
        fbPidVent(
            xEn := FALSE,
            rPv := aiTrockenluftFeucht,
            rSetp := rTrockenluftFeuchteSoll,
            xManualMode := TRUE,
            rManualValue := 0.0,
            xHold := FALSE,
            rHighLimit := rVentHighLimit,
            rLowLimit := rVentLowLimit,
            rDeadband := rVentDeadband,
            xAutoTune := FALSE,
            rAutoTuneValue := 0.0,
            rKp := rVentKp,
            uiTi := uiVentTi,
            uiTd := uiVentTd,
            xReset := FALSE
        );

ELSE
    gAktoren.xFrgVentilator       := FALSE;
    gAktoren.xFrgLuftaufbereiter  := FALSE;
    gAktoren.xFrgAbluftventilator := FALSE;
    aoFuVentilator := 0.0;
    aoLeistVorgLuftaufber := 0.0;
END_CASE;

(* ================================================================================ File : AktorenMapping.st Project : CControl_Lite Controller : Schneider / EcoStruxure Machine Expert HVAC Author : RIG Automation Created : 2026-04-03 Version : V0.03 Description : Zyklisches Aktoren-Mapping für die Kleinsteuerung.
Enthaltene Aktoren: - Boxenklappe 1 - Boxenklappe 2 - Ventilator 1 - Luftaufbereiter - Abluftventilator
Die Boxenklappen werden über den Funktionsbaustein fbBoxenklappe angesteuert. Der Aufbau orientiert sich an der bewährten Vorlage fbBoxenKlappenanst.
================================================================================ Change History -------------------------------------------------------------------------------- Version | Date | Author | Description -------------------------------------------------------------------------------- V0.03 | 2026-04-03 | RIG Automation | Anpassung auf FB fbBoxenklappe ================================================================================ *)
gAktoren.xQuitFehler := gQuitErr;
(* ------------------------------------------------------------------------------- Analogwerte begrenzen ------------------------------------------------------------------------------- *) IF aoFuVentilator < 0.0 THEN aoFuVentilator := 0.0; ELSIF aoFuVentilator > 100.0 THEN aoFuVentilator := 100.0; END_IF;
IF aoLeistVorgLuftaufber < 0.0 THEN aoLeistVorgLuftaufber := 0.0; ELSIF aoLeistVorgLuftaufber > 100.0 THEN aoLeistVorgLuftaufber := 100.0; END_IF;
(* =============================================================================== BOXENKLAPPE 1 =============================================================================== TRUE = öffnen FALSE = schließen ------------------------------------------------------------------------------- *) fbBoxenklappe1( Oeffnen := gAktoren.Box[1].xSollOffen, Schliessen := NOT gAktoren.Box[1].xSollOffen, EndlageOffen := diBox1Offen, EndlageGeschl := diBox1Geschl, EndlagenVhd := TRUE, LaufzeitOeffnen := gBetriebsparameter.KlappenBoxen[1].Laufzeit, LaufzeitSchliessen := gBetriebsparameter.KlappenBoxen[1].Laufzeit, Stoerung := diBox1Offen AND diBox1Geschl, QuitFehler := gAktoren.xQuitFehler );
(* Physischer Ausgang Wechsler-Relais *) doFrgBox1 := fbBoxenklappe1.OeffnenOut;
(* ------------------------------------------------------------------------------- Status Boxenklappe 1 ------------------------------------------------------------------------------- *) IF fbBoxenklappe1.FehlerLaufzeitOeffnen OR fbBoxenklappe1.FehlerLaufzeitSchliessen OR (diBox1Offen AND diBox1Geschl) THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_STOERUNG; ELSIF fbBoxenklappe1.OeffnenOut AND NOT diBox1Offen THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_IN_BEWEGUNG; ELSIF fbBoxenklappe1.SchliessenOut AND NOT diBox1Geschl THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_IN_BEWEGUNG; ELSIF diBox1Offen THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_OFFEN; ELSIF diBox1Geschl THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_GESCHLOSSEN; ELSE gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_UNBEKANNT; END_IF;
(* =============================================================================== BOXENKLAPPE 2 =============================================================================== TRUE = öffnen FALSE = schließen ------------------------------------------------------------------------------- *) fbBoxenklappe2( Oeffnen := gAktoren.Box[2].xSollOffen, Schliessen := NOT gAktoren.Box[2].xSollOffen, EndlageOffen := diBox2Offen, EndlageGeschl := diBox2Geschl, EndlagenVhd := TRUE, LaufzeitOeffnen := gBetriebsparameter.KlappenBoxen[2].Laufzeit, LaufzeitSchliessen := gBetriebsparameter.KlappenBoxen[2].Laufzeit, Stoerung := diBox2Offen AND diBox2Geschl, QuitFehler := gAktoren.xQuitFehler );
(* Physischer Ausgang Wechsler-Relais *) doFrgBox2 := fbBoxenklappe2.OeffnenOut;
(* ------------------------------------------------------------------------------- Status Boxenklappe 2 ------------------------------------------------------------------------------- *) IF fbBoxenklappe2.FehlerLaufzeitOeffnen OR fbBoxenklappe2.FehlerLaufzeitSchliessen OR (diBox2Offen AND diBox2Geschl) THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_STOERUNG; ELSIF fbBoxenklappe2.OeffnenOut AND NOT diBox2Offen THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_IN_BEWEGUNG; ELSIF fbBoxenklappe2.SchliessenOut AND NOT diBox2Geschl THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_IN_BEWEGUNG; ELSIF diBox2Offen THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_OFFEN; ELSIF diBox2Geschl THEN gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_GESCHLOSSEN; ELSE gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_UNBEKANNT; END_IF;
(* =============================================================================== VENTILATOR 1 =============================================================================== Direkte Ansteuerung: - digitale Freigabe - analoge Drehzahlvorgabe ------------------------------------------------------------------------------- *)
IF doFrgVentilator THEN gStatusAnlage.Aktor[AKTOR_VENTILATOR] := STATUS_AKTIV; ELSE gStatusAnlage.Aktor[AKTOR_VENTILATOR] := STATUS_NICHT_AKTIV; END_IF;
(* =============================================================================== LUFTAUFBEREITER =============================================================================== Direkte Ansteuerung Analoge Leistungsvorgabe analog zum Heizregister-Prinzip: - digitale Freigabe - analoger Sollwert ------------------------------------------------------------------------------- *)
IF gAktoren.xFrgLuftaufbereiter THEN IF diStoerLuftaufber THEN gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_STOERUNG; ELSIF diBetriebLuftaufber THEN gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_AKTIV; ELSE gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_BEREIT; END_IF; ELSE IF diStoerLuftaufber THEN gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_STOERUNG; ELSE gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_NICHT_AKTIV; END_IF; END_IF;
doFrgLuftaufber := gAktoren.xFrgLuftaufbereiter;
(* =============================================================================== ABLUFTVENTILATOR =============================================================================== Direkte Ansteuerung ------------------------------------------------------------------------------- *)
IF gAktoren.xFrgAbluftventilator THEN gStatusAnlage.Aktor[AKTOR_ABLUFTVENTILATOR] := STATUS_AKTIV; ELSE gStatusAnlage.Aktor[AKTOR_ABLUFTVENTILATOR] := STATUS_NICHT_AKTIV; END_IF;
doFrgAbluftventilator := gAktoren.xFrgAbluftventilator;

data.iecDecl:
PROGRAM aktorenMapping

VAR
	xStateEntryBox1 : BOOL := TRUE;
	uiStepBox1 : UINT := 0;
	xFehlerLaufzeitOeffnenBox1 : BOOL := FALSE;
	xFehlerLaufzeitSchliessenBox1 : BOOL := FALSE;
	xKlappeIstOffenBox1 : BOOL := FALSE;
	xKlappeIstGeschlBox1 : BOOL := FALSE;
	tonLaufzeitBox1 : TON;
	tonAnzVerzBox1 : TON;
	xStateEntryBox2 : BOOL := TRUE;
	uiStepBox2 : UINT := 0;
	xFehlerLaufzeitOeffnenBox2 : BOOL := FALSE;
	xFehlerLaufzeitSchliessenBox2 : BOOL := FALSE;
	xKlappeIstOffenBox2 : BOOL := FALSE;
	xKlappeIstGeschlBox2 : BOOL := FALSE;
	tonLaufzeitBox2 : TON;
	tonAnzVerzBox2 : TON;
	xBox1OeffnenOut : BOOL := FALSE;
	xBox1SchliessenOut : BOOL := FALSE;
	xBox2OeffnenOut : BOOL := FALSE;
	xBox2SchliessenOut : BOOL := FALSE;
	xStoerungBox1 : BOOL := FALSE;
	xStoerungBox2 : BOOL := FALSE;
	fbBoxenklappe1 : fbBoxenklappe;
	fbBoxenklappe2 : fbBoxenklappe;
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : HMIMappingCyclic.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-03-19
 Version     : V0.01
 Description :
    Zyklische Übergabe von Ein-/Ausgängen und aufbereiteten Messwerten an die HMI.

    Dieses Programm trennt bewusst zwischen:
      - Hardware-/Prozessabbild
      - interner Programmlogik
      - Visualisierungsdaten

    Die HMI liest ausschließlich die hier beschriebenen HMI-Variablen.
    Dadurch bleibt die Visualisierung von der eigentlichen I/O-Anbindung entkoppelt.

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.01   | 2026-03-19 | RIG Automation  | Initialerstellung HMI-Mapping für
                                        | digitale/analoge Ein- und Ausgänge
================================================================================
*)

(*
===============================================================================
 HMI-DATEN ZYKLISCH AKTUALISIEREN
-------------------------------------------------------------------------------
 Alle für die Visualisierung relevanten Ein- und Ausgangswerte werden in
 sprechende HMI-Variablen kopiert.
===============================================================================
*)

(*
---------------------------------------------------------------------------
Standard-Filterzeiten
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FilterzeitFrischluft := Sensoren_FilterzeitFrischluft;
gBetriebsparameter.Sensoren.FilterzeitAbluft := Sensoren_FilterzeitAbluft;

(*
---------------------------------------------------------------------------
Messbereiche Frischluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FrischlTempMessberMin := Sensoren_FrischlTempMessberMin;
gBetriebsparameter.Sensoren.FrischlTempMessberMax := Sensoren_FrischlTempMessberMax;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin := Sensoren_FrischlFeuchteMessberMin;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax := Sensoren_FrischlFeuchteMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Abluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.AbluftTempMessberMin := Sensoren_AbluftTempMessberMin;
gBetriebsparameter.Sensoren.AbluftTempMessberMax := Sensoren_AbluftTempMessberMax;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin := Sensoren_AbluftFeuchtMessberMin;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax := Sensoren_AbluftFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Trockenluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.TrockenlTempMessberMin := Sensoren_TrockenlTempMessberMin;
gBetriebsparameter.Sensoren.TrockenlTempMessberMax := Sensoren_TrockenlTempMessberMax;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin := Sensoren_TrockenlFeuchtMessberMin;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax := Sensoren_TrockenlFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Sensor-Offsets
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.OffsetFrischluftTemp := Sensoren_OffsetFrischluftTemp;
gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte := Sensoren_OffsetFrischluftFeuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp := Sensoren_OffsetAbluftBox1Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte := Sensoren_OffsetAbluftBox1Feuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp := Sensoren_OffsetAbluftBox2Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte := Sensoren_OffsetAbluftBox2Feuchte;
gBetriebsparameter.Sensoren.OffsetTrockenluftTemp := Sensoren_OffsetTrockenluftTemp;
gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte := Sensoren_OffsetTrockenluftFeuchte;
gBetriebsparameter.Sensoren.OffsetStocktemp := Sensoren_OffsetStocktemp;

(*
---------------------------------------------------------------------------
Ausstattung / aktivierte Anlagenteile
---------------------------------------------------------------------------
Diese Werte sind vorläufige Defaultwerte und müssen später an die reale
Anlagenausstattung angepasst werden.
---------------------------------------------------------------------------
*)
gBetriebsparameter.Ausstattung.Box2 := Ausstattung_Box2;
gBetriebsparameter.Ausstattung.Luftaufbereiter := Ausstattung_Luftaufbereiter;
gBetriebsparameter.Ausstattung.Abluftventilator := Ausstattung_Abluftventilator;
gBetriebsparameter.Ausstattung.SensorFrischluft := Ausstattung_SensorFrischluft;
gBetriebsparameter.Ausstattung.SensorAbluftBox1 := Ausstattung_SensorAbluftBox1;
gBetriebsparameter.Ausstattung.SensorAbluftBox2 := Ausstattung_SensorAbluftBox2;
gBetriebsparameter.Ausstattung.SensorTrockenluft := Ausstattung_SensorTrockenluft;
gBetriebsparameter.Ausstattung.SensorStocktemp := Ausstattung_SensorStocktemp;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe1 := Ausstattung_EndlagenVhdBoxenklappe1;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe2 := Ausstattung_EndlagenVhdBoxenklappe2;

(*
---------------------------------------------------------------------------
Klappen/Boxen
---------------------------------------------------------------------------
*)
gBetriebsparameter.KlappenBoxen[1].Laufzeit := Klappen_Boxen_Box1_Laufzeit;
gBetriebsparameter.KlappenBoxen[2].Laufzeit := Klappen_Boxen_Box2_Laufzeit;


(*
-------------------------------------------------------------------------------
 Betriebsart / allgemeiner Zustand
-------------------------------------------------------------------------------
*)
HMI_TEST_diIoTestAktiv:= (gAktModus = IOTEST);

(*
-------------------------------------------------------------------------------
 Digitale Eingänge an HMI übergeben
-------------------------------------------------------------------------------
*)
HMI_IN_diBox1Offen  		:= diBox1Offen;
HMI_IN_diBox1Geschl  		:= diBox1Geschl;
HMI_IN_diBox2Offen  		:= diBox2Offen;
HMI_IN_diBox2Geschl 		:= diBox2Geschl;
HMI_IN_diBetriebLuftaufber 	:= diBetriebLuftaufber;
HMI_IN_diStoerLuftaufber  	:= diStoerLuftaufber;

(*
-------------------------------------------------------------------------------
 Analoge Eingänge an HMI übergeben
-------------------------------------------------------------------------------
 Es werden bereits skalierte Engineering-Werte an die HMI übergeben.
-------------------------------------------------------------------------------
*)
HMI_IN_aiFrischluftTemp       := gStatusAnlage.FrischluftTemperatur;
HMI_IN_aiFrischluftFeuchte    := gStatusAnlage.FrischluftFeuchte;
HMI_IN_aiAbluftBox1Temp       := gStatusAnlage.AbluftBox1Temp;
HMI_IN_aiAbluftBox1Feuchte    := gStatusAnlage.AbluftBox1Feuchte;
HMI_IN_aiTrockenluftTemp      := gStatusAnlage.TrockenluftTemperatur;
HMI_IN_aiTrockenluftFeuchte   := gStatusAnlage.TrockenluftFeuchte;
HMI_IN_aiAbluftBox2Temp       := gStatusAnlage.AbluftBox2Temp;
HMI_IN_aiAbluftBox2Feuchte    := gStatusAnlage.AbluftBox2Feuchte;
HMI_IN_aiStocktemp            := gStatusAnlage.StockTemperatur;


(*
-------------------------------------------------------------------------------
 Digitale Ausgänge an HMI übergeben
-------------------------------------------------------------------------------
 Hier werden die internen Soll-/Freigabesignale visualisiert.
-------------------------------------------------------------------------------
*)
HMI_IN_doFrgLuftaufber     		:= doFrgLuftaufber;
HMI_IN_doFrgBox1            	:= doFrgBox1;
HMI_IN_doFrgBox2           		:= doFrgBox2;
HMI_IN_doFrgAbluftvent	     	:= doFrgAbluftventilator;
HMI_IN_doFrgVentilator	     	:= doFrgVentilator;

(*
-------------------------------------------------------------------------------
 Analogausgänge an HMI übergeben
-------------------------------------------------------------------------------
 Die HMI erhält die Engineering-Sollwerte sowie optional die bereits
 skalierten Hardwarewerte.
-------------------------------------------------------------------------------
*)
HMI_IN_aoFuVentilator   	  := aoFuVentilator;
HMI_IN_aoLeistVorgLuftaufber  := aoLeistVorgLuftaufber;

(*
-------------------------------------------------------------------------------
 I/O-Testdaten an HMI übergeben
-------------------------------------------------------------------------------
 So sieht man in der Visu sofort, ob Testbetrieb aktiv ist und welche
 Testwerte gerade anliegen.
-------------------------------------------------------------------------------
*)

(* PLC OUT - HMI IN *)

//analog
HMI_TEST_diBox1Offen     		:= gIoTest.DigitalIn.diBox1Offen;
HMI_TEST_diBox1Geschl  	 		:= gIoTest.DigitalIn.diBox1Geschl;
HMI_TEST_diBox2Offen   		 	:= gIoTest.DigitalIn.diBox2Offen;
HMI_TEST_diBox2Geschl    		:= gIoTest.DigitalIn.diBox2Geschl;
HMI_TEST_diBetriebLuftaufber  	:= gIoTest.DigitalIn.diBetriebLuftaufber;
HMI_TEST_diStoerLuftaufber  	:= gIoTest.DigitalIn.diStoerLuftaufber;

//digital
HMI_TEST_aiFrischluftTemp  		:= gIoTest.AnalogIn.aiFrischluftTemp;
HMI_TEST_aiFrischluftFeuchte  	:= gIoTest.AnalogIn.aiFrischluftFeuchte;
HMI_TEST_aiAbluftBox1Temp     	:= gIoTest.AnalogIn.aiAbluftBox1Temp;
HMI_TEST_aiAbluftBox1Feuchte  	:= gIoTest.AnalogIn.aiAbluftBox1Feucht;
HMI_TEST_aiTrockenluftTemp 	  	:= gIoTest.AnalogIn.aiTrockenluftTemp;
HMI_TEST_aiTrockenluftFeuchte 	:= gIoTest.AnalogIn.aiTrockenluftFeucht;
HMI_TEST_aiAbluftBox2Temp  	  	:= gIoTest.AnalogIn.aiAbluftBox2Temp;
HMI_TEST_aiAbluftBox2Feuchte  	:= gIoTest.AnalogIn.aiAbluftBox2Feucht;
HMI_TEST_aiStocktemp   		  	:= gIoTest.AnalogIn.aiStocktemp;

(* HMI IN - PLC OUT *)

//digital
gIoTest.DigitalOut.doFrgLuftaufber			:= HMI_TEST_doFrgLuftaufber;
gIoTest.DigitalOut.doFrgBox1				:= HMI_TEST_doFrgBox1;
gIoTest.DigitalOut.doFrgBox2				:= HMI_TEST_doFrgBox2;
gIoTest.DigitalOut.doFrgAbluftventilator	:= HMI_TEST_doFrgAbluftventilator;
gIoTest.DigitalOut.doFrgVentilator			:= HMI_TEST_doFrgVentilator;

//analog
gIoTest.AnalogOut.aoFuVentilator			:= HMI_TEST_aoFuVentilator;
gIoTest.AnalogOut.aoLeistVorgLuftaufber 	:= HMI_TEST_aoLeistVorgLuftaufber;

(*
================================================================================
File        : StartStoppCyclic.st
Project     : CControl_Lite
Description :
    Start-/Stopp-Auswertung für 2-Box-Lite-Anlage.
================================================================================
*)

(* Betriebsart *)
gCmdAnlage.Auto := NOT HMI_TEST_diIoTestAktiv;
gCmdAnlage.Test := HMI_TEST_diIoTestAktiv;

(* Boxaktivität *)
xBox1Aktiv := (diBox1Offen OR gAktoren.Box[1].xSollOffen);

IF gBetriebsparameter.Ausstattung.Box2 THEN
    xBox2Aktiv := (diBox2Offen OR gAktoren.Box[2].xSollOffen);
ELSE
    xBox2Aktiv := FALSE;
END_IF;

xMindEineBoxAktiv := xBox1Aktiv OR xBox2Aktiv;

(* externe Signale optional *)
xExternStart := gCmdAnlage.StartExtern;
xExternStop  := gCmdAnlage.StoppExtern;

(* Fehlerstopp vorerst ohne Alarmmatrix *)
gCmdAnlage.FehlerStopp := FALSE;

(* Start/Stop *)
gCmdAnlage.Start := gCmdAnlage.Auto
                    AND (xMindEineBoxAktiv OR xExternStart)
                    AND NOT gCmdAnlage.FehlerStopp;

gCmdAnlage.Stopp := gCmdAnlage.Auto
                    AND ((NOT xMindEineBoxAktiv) OR xExternStop OR gCmdAnlage.FehlerStopp);

data.iecDecl:
PROGRAM StartStoppCyclic

VAR
    xBox1Aktiv : BOOL;
    xBox2Aktiv : BOOL;
    xMindEineBoxAktiv : BOOL;
    xExternStart : BOOL;
    xExternStop : BOOL;
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : fbBoxenklappe.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-03
 Version     : V0.02
 Description :
    Funktionsbaustein zur Ansteuerung einer Boxenklappe mit einem Wechsler-
    Relais.

    Funktionsprinzip:
      - nicht angesteuert = Richtung A
      - angesteuert       = Richtung B

    Für die Anwendung in CControl_Lite gilt:
      - OeffnenOut     = TRUE
      - SchliessenOut  = FALSE

    Funktionsumfang:
      - Laufzeitüberwachung Öffnen/Schließen
      - Fehlerquittierung
      - Endlagenbehandlung
      - Betrieb auch ohne Endlagen möglich
      - 40 ms Anzugsverzögerung

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.02   | 2026-04-03 | RIG Automation  | Initialerstellung
================================================================================
*)

IF (NOT Stoerung) THEN

    (*
    ---------------------------------------------------------------------------
    Fehlerquittierung Laufzeitüberwachung
    ---------------------------------------------------------------------------
    *)
    IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitOeffnen := FALSE;
    END_IF;

    IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitSchliessen := FALSE;
    END_IF;


    CASE uiStep OF

        (*
        =======================================================================
        WARTEN
        =======================================================================
        *)
        0:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
            END_IF;

            (* state during *)
            IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitOeffnen := FALSE;
            END_IF;

            IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitSchliessen := FALSE;
            END_IF;

            (* state exit *)
            IF EndlagenVhd OR (LaufzeitOeffnen = 0) THEN
                IF Oeffnen AND NOT FehlerLaufzeitOeffnen THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            ELSE
                IF Oeffnen AND NOT KlappeIstOffenOut THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            END_IF;

            IF EndlagenVhd OR (LaufzeitSchliessen = 0) THEN
                IF Schliessen AND NOT FehlerLaufzeitSchliessen THEN
                    stateEntry := TRUE;
                    uiStep  := 2;
                END_IF;
            ELSE
                IF Schliessen AND NOT KlappeIstGeschlOut THEN
                    stateEntry := TRUE;
                    uiStep := 2;
                END_IF;
            END_IF;


        (*
        =======================================================================
        OEFFNEN
        =======================================================================
        *)
        1:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                SchliessenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := OeffnenOut AND NOT EndlageOffen, PT := LaufzeitOeffnen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            OeffnenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Oeffnen) OR Schliessen OR (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstOffenOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                    FehlerLaufzeitOeffnen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep  := 0;
            END_IF;


        (*
        =======================================================================
        SCHLIESSEN
        =======================================================================
        *)
        2:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                OeffnenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := SchliessenOut AND NOT EndlageGeschl, PT := LaufzeitSchliessen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            SchliessenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Schliessen) OR Oeffnen OR (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstGeschlOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                    FehlerLaufzeitSchliessen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep := 0;
            END_IF;

    END_CASE;

ELSE
    OeffnenOut := FALSE;
    SchliessenOut := FALSE;
    stateEntry := TRUE;
    FehlerLaufzeitOeffnen := FALSE;
    FehlerLaufzeitSchliessen := FALSE;
    KlappeIstGeschlOut := FALSE;
    KlappeIstOffenOut := FALSE;
    uiStep := 0;
END_IF;
